{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A playful, premium cohort experience for tuned rest and restorative sound gatherings in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 100 30" aria-hidden="true"><rect width="100" height="30" rx="6" fill="#2b2b2b"/><text x="50" y="19" fill="#fff" font-family="sans-serif" font-size="10" text-anchor="middle">{{BUSINESS_NAME}}</text></svg>
      <div class="tag">{{TAGLINE}}</div>
    </div>
    <nav class="main-nav" aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Studio</a>
      <a href="faq.html">FAQ</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button id="try-now" class="link-button">Try it now</button>
    </nav>
  </header>

  <main>
    <!-- HERO (split diagonal layout) -->
    <section class="hero">
      <div class="hero-left">
        <h1>Sound gatherings with a hint of curiosity</h1>
        <p class="lead">Join a seasonal cohort of listeners for layered tones, gentle guidance, and playful prompts that help you land into a peaceful evening. Seats are limited — courses run in groups to build a shared rhythm.</p>
        <div class="hero-actions">
          <a class="btn primary" href="events.html">Explore upcoming cohorts</a>
          <a class="btn ghost" href="book.html">Reserve a consult</a>
        </div>
        <ul class="quick-info">
          <li><strong>Format:</strong> Cohort series — weekly sessions</li>
          <li><strong>Where:</strong> {{CITY}}, {{STATE}}</li>
          <li><strong>Contact:</strong> <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
        </ul>
      </div>
      <div class="hero-right">
        <svg class="pattern" viewBox="0 0 600 400" preserveAspectRatio="none" aria-hidden="true">
          <defs>
            <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
              <rect width="40" height="40" fill="#f8fafc"/>
              <path d="M0 20 L20 0 L40 20" stroke="#c7e3e1" stroke-width="1.5" fill="none"/>
              <circle cx="10" cy="30" r="2.2" fill="#e6f6f4"/>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#p)"/>
        </svg>
        <div class="next-cohort-card">
          <h3>Next cohort meeting</h3>
          <div id="next-event">
            <div class="event-meta">
              <div class="date">Sat • Mar 20 • 6:30pm</div>
              <div class="location">Studio A — {{CITY}}</div>
            </div>
            <div class="availability">Available spots: <span id="available-spots">6</span></div>
            <div class="seat-selector">
              <label for="seat-count">Reserve seats</label>
              <input type="range" id="seat-count" min="1" max="6" value="1">
              <div class="seat-output">Seats: <span id="seat-number">1</span></div>
              <button id="reserve" class="btn small">Hold these seats (local demo)</button>
            </div>
            <details class="packing">
              <summary>What to bring &rarr;</summary>
              <form id="packing-form">
                <label><input type="checkbox" name="items" value="mat"> Yoga mat or cushion</label>
                <label><input type="checkbox" name="items" value="blanket"> Warm blanket</label>
                <label><input type="checkbox" name="items" value="water"> Water bottle</label>
                <label><input type="checkbox" name="items" value="journal"> Journal & pen</label>
                <label><input type="checkbox" name="items" value="eye-mask"> Eye cover</label>
                <div class="packing-actions">
                  <button id="pack-generate" type="button" class="btn">Generate list</button>
                  <button id="pack-reset" type="button" class="btn ghost">Reset</button>
                </div>
                <pre id="packing-output" class="pack-output" aria-live="polite"></pre>
              </form>
            </details>
          </div>
        </div>
      </div>
    </section>

    <!-- GALLERY (simple showcase) -->
    <section class="gallery">
      <h2>Vignettes from past gatherings</h2>
      <p class="muted">Scenes composed from the cohort — tones, community, gentle reflection.</p>
      <div class="grid">
        <div class="card"> <div class="silhouette">sound + stillness</div> </div>
        <div class="card"> <div class="silhouette">guided breath</div> </div>
        <div class="card"> <div class="silhouette">journaling pause</div> </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT (include contraindications) -->
    <section class="expectations">
      <h2>How the cohort runs</h2>
      <ol>
        <li>Brief check-in and intention-setting</li>
        <li>Layered sound offerings — gongs, bowls, subtle percussive textures</li>
        <li>Guided breath or journaling prompt between pieces</li>
        <li>Gentle close and short group reflection</li>
      </ol>
      <aside class="disclaimer">
        <strong>Contraindications</strong>
        <p>If you have severe tinnitus, a history of seizures, recent head trauma, or are pregnant in your first trimester, consult a healthcare professional before attending. This practice complements care but is not a substitute for medical advice.</p>
      </aside>
    </section>

    <!-- OBJECTIONS (FAQ-style quick answers) -->
    <section class="objections">
      <h2>Questions people often have</h2>
      <ul>
        <li><strong>I'm new — will I be out of place?</strong>
          <p>All levels welcome. We guide you through simple steps so you can arrive curious and leave lighter.</p>
        </li>
        <li><strong>What should I wear?</strong>
          <p>Comfortable layers that let you sit or lie down easily. Bring socks if you prefer.</p>
        </li>
        <li><strong>Is it religious?</strong>
          <p>No. Practices are secular and invitation-based, using sound and attentional prompts.</p>
        </li>
      </ul>
    </section>

    <!-- CTA -->
    <section class="book-cta">
      <h2>Ready to join a small cohort?</h2>
      <p>Our cohort model helps people arrive together and leave with a shared sense of ease. Book a seat or schedule a private consult to explore what's right for you.</p>
      <div class="cta-actions">
        <a class="btn primary" href="book.html">Claim a spot</a>
        <a class="btn ghost" href="contact.html">Ask a question</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div>© <span id="year"></span> {{BUSINESS_NAME}} — A cohort studio in {{CITY}}, {{STATE}}.</div>
    <div class="legal"><a href="privacy.html">Privacy</a> • <a href="terms.html">Terms</a></div>
  </footer>

  <!-- GUIDED EXERCISE MODALS -->
  <div id="modal" class="modal" aria-hidden="true">
    <div class="modal-inner" role="dialog" aria-modal="true">
      <button id="modal-close" class="modal-close" aria-label="Close">×</button>
      <div class="modal-content">
        <h3 id="modal-title">Try a short practice</h3>
        <div class="modal-tabs">
          <button data-mode="breath" class="tab active">Breathing</button>
          <button data-mode="journal" class="tab">Journaling</button>
        </div>
        <div id="modal-body">
          <!-- content filled by JS -->
        </div>
        <div class="modal-actions">
          <button id="modal-start" class="btn primary">Start</button>
          <button id="modal-skip" class="btn ghost">Close</button>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
