{"path":"assets/css/styles.css","content":"/* Playful premium styles — split diagonal layout */
:root{
  --bg:#fcfdfd;
  --muted:#7b8a89;
  --accent:#2aa198;
  --dark:#1f2b2b;
  --card:#ffffff;
  --glass:rgba(255,255,255,0.6);
  font-synthesis: none;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; color:var(--dark); background:linear-gradient(180deg,#fbfdfd 0%, #f3fbfa 100%);} 
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;border-bottom:1px solid #eef6f5;background:linear-gradient(90deg,rgba(255,255,255,0.8),rgba(250,255,254,0.4));position:sticky;top:0;backdrop-filter:blur(6px);}
.brand{display:flex;align-items:center;gap:12px}
.brand .tag{font-size:12px;color:var(--muted)}
.main-nav a{margin-left:14px;color:var(--dark);text-decoration:none;font-weight:600}
.main-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.main-nav .link-button{border:none;background:none;color:var(--accent);font-weight:700;margin-left:8px;cursor:pointer}
.hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:stretch;padding:48px;position:relative}
.hero-left{padding:28px}
.hero h1{font-size:34px;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 20px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid transparent;font-weight:700}
.btn.primary{background:var(--dark);color:#fff}
.btn.ghost{background:transparent;border:1px solid #dceeea;color:var(--dark)}
.btn.small{padding:6px 10px;font-size:13px}
.quick-info{list-style:none;padding:0;margin:18px 0 0;color:var(--muted)}
.quick-info li{margin-bottom:6px}
.hero-right{position:relative}
.pattern{width:100%;height:260px;border-radius:12px;box-shadow:0 8px 20px rgba(21,31,30,0.06)}
.next-cohort-card{position:absolute;right:14px;top:30px;background:var(--card);padding:16px;border-radius:12px;width:320px;box-shadow:0 6px 18px rgba(22,31,30,0.06)}
.next-cohort-card h3{margin:0 0 8px}
.event-meta{font-size:13px;color:var(--muted);margin-bottom:8px}
.availability{font-weight:700;margin-bottom:8px}
.seat-selector{display:flex;flex-direction:column;gap:8px}
.seat-selector input[type=range]{width:100%}
.seat-output{font-size:13px;color:var(--muted)}
.packing summary{cursor:pointer}
.packing-actions{display:flex;gap:10px;margin-top:10px}
.pack-output{background:#f7fffe;padding:10px;border-radius:8px;border:1px dashed #e2f5f1;margin-top:10px}
.gallery{padding:28px}
.gallery .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}
.card{background:linear-gradient(180deg,#ffffff,#f8fffe);border-radius:10px;padding:28px;min-height:120px;display:flex;align-items:center;justify-content:center;color:var(--muted);box-shadow:0 6px 16px rgba(31,44,43,0.04)}
.expectations{padding:28px;background:linear-gradient(180deg,rgba(226,250,247,0.4),transparent);}
.disclaimer{background:#fff;border-left:4px solid var(--accent);padding:12px;margin-top:12px;border-radius:8px}
.objections{padding:28px}
.objections ul{list-style:none;padding:0}
.objections li{padding:12px 0;border-bottom:1px dashed #eef9f7}
.book-cta{padding:28px;background:linear-gradient(90deg,#effffb,#ffffff);text-align:center}
.site-footer{padding:18px 28px;border-top:1px solid #eef6f5;display:flex;justify-content:space-between}
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(14,22,21,0.35);z-index:60}
.modal[aria-hidden="false"]{display:flex}
.modal-inner{background:var(--card);padding:18px;border-radius:12px;width:540px;max-width:92%;box-shadow:0 24px 60px rgba(10,20,20,0.45)}
.modal-close{position:absolute;right:22px;top:18px;background:none;border:none;font-size:20px}
.modal-tabs{display:flex;gap:8px;margin-bottom:12px}
.modal-tabs .tab{padding:8px 12px;border-radius:8px;border:1px solid #e6f6f3;background:transparent;cursor:pointer}
.modal-tabs .tab.active{background:var(--accent);color:#fff}
.modal-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:12px}
.silhouette{font-size:14px;color:var(--muted)}
@media(max-width:900px){
  .hero{grid-template-columns:1fr;}
  .hero-right{order:-1}
  .gallery .grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Local JS for seat selector, packing list generator, and guided exercise modals
(function(){
  // Basic helpers
  function $(sel, ctx){return (ctx||document).querySelector(sel)}
  function $all(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year update
  $('#year').textContent = new Date().getFullYear()

  // Seat selector logic (local demo)
  var seatRange = $('#seat-count')
  var seatNumber = $('#seat-number')
  var available = $('#available-spots')
  var reserveBtn = $('#reserve')
  var spots = 6 // initial

  function updateSeats(){
    seatNumber.textContent = seatRange.value
  }
  seatRange.addEventListener('input', updateSeats)

  reserveBtn.addEventListener('click', function(){
    var want = parseInt(seatRange.value,10)
    if(want <= spots){
      spots -= want
      available.textContent = spots
      alert('Local demo: held ' + want + ' seat(s). This is a mock reservation.')
      if(spots === 0){
        reserveBtn.disabled = true
      }
    } else {
      alert('Not enough spots available in this demo.')
    }
  })

  // Packing list generator
  var packForm = $('#packing-form')
  var packGen = $('#pack-generate')
  var packReset = $('#pack-reset')
  var packOut = $('#packing-output')

  function generatePacking(){
    var checks = packForm.querySelectorAll('input[name="items"]:checked')
    if(checks.length === 0){
      packOut.textContent = 'No items selected — consider a cozy blanket and a bottle of water.'
      return
    }
    var lines = ['Bring these to the session:']
    checks.forEach(function(c,i){ lines.push((i+1)+'. '+ c.parentNode.textContent.trim()) })
    lines.push('\nQuick tips:\n- Layer clothing\n- Arrive 10 minutes early\n- Keep your phone on low or airplane mode')
    packOut.textContent = lines.join('\n')
  }
  packGen.addEventListener('click', generatePacking)
  packReset.addEventListener('click', function(){
    $all('input[name="items"]', packForm).forEach(function(i){i.checked=false})
    packOut.textContent = ''
  })

  // Guided exercise modal
  var modal = $('#modal')
  var tryBtn = $('#try-now')
  var modalClose = $('#modal-close')
  var modalTitle = $('#modal-title')
  var modalBody = $('#modal-body')
  var modalStart = $('#modal-start')
  var modalSkip = $('#modal-skip')
  var tabs = $all('.modal-tabs .tab')
  var currentMode = 'breath'
  var breathTimer = null

  function openModal(){
    modal.setAttribute('aria-hidden','false')
    document.body.style.overflow = 'hidden'
    renderModal(currentMode)
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true')
    document.body.style.overflow = ''
    stopBreath()
  }
  tryBtn.addEventListener('click', openModal)
  modalClose.addEventListener('click', closeModal)
  modalSkip.addEventListener('click', closeModal)

  tabs.forEach(function(t){
    t.addEventListener('click', function(){
      tabs.forEach(function(x){x.classList.remove('active')})
      t.classList.add('active')
      currentMode = t.getAttribute('data-mode')
      renderModal(currentMode)
    })
  })

  function renderModal(mode){
    if(mode==='breath'){
      modalTitle.textContent = 'Short breathing guide'
      modalBody.innerHTML = ''
      var p = document.createElement('p')
      p.textContent = 'A short 3-minute breathing anchor: follow the circle and breathe with the cue.'
      var circle = document.createElement('div')
      circle.id = 'breath-circle'
      circle.className = 'breath-circle'
      var guide = document.createElement('p')
      guide.id = 'breath-guide'
      guide.className = 'muted small'
      guide.textContent = 'Ready? Press Start.'
      modalBody.appendChild(p)
      modalBody.appendChild(circle)
      modalBody.appendChild(guide)
    } else if(mode==='journal'){
      modalTitle.textContent = 'Two-minute journaling prompt'
      modalBody.innerHTML = ''
      var p = document.createElement('p')
      p.textContent = 'Write for two minutes: a prompt to clear the edges of your day.'
      var prompt = document.createElement('blockquote')
      prompt.textContent = 'What do I want to carry forward from today, and what can I leave behind?'
      prompt.style.padding='10px'; prompt.style.background='#f6fffe'; prompt.style.borderRadius='8px'; prompt.style.marginTop='8px'
      var textarea = document.createElement('textarea')
      textarea.rows = 6; textarea.style.width='100%'; textarea.placeholder='Write a few lines...'
      modalBody.appendChild(p)
      modalBody.appendChild(prompt)
      modalBody.appendChild(textarea)
    }
  }

  modalStart.addEventListener('click', function(){
    if(currentMode==='breath'){
      startBreath()
    } else {
      startJournalTimer()
    }
  })

  function startBreath(){
    var guide = $('#breath-guide')
    var circle = $('#breath-circle')
    var steps = [ {label:'Breathe in',ms:4000},{label:'Hold',ms:2000},{label:'Breathe out',ms:6000} ]
    var i=0
    guide.textContent = steps[0].label
    circle.style.transition = 'transform 4s ease-in-out'
    circle.style.transform = 'scale(1.2)'
    stopBreath()
    breathTimer = setInterval(function(){
      i = (i+1) % steps.length
      guide.textContent = steps[i].label
      // alter scale for simple visual cue
      if(steps[i].label==='Breathe in'){
        circle.style.transition = 'transform 4s ease-in-out'
        circle.style.transform = 'scale(1.2)'
      } else if(steps[i].label==='Hold'){
        circle.style.transition = 'transform 2s ease-in-out'
        circle.style.transform = 'scale(1.05)'
      } else {
        circle.style.transition = 'transform 6s ease-in-out'
        circle.style.transform = 'scale(0.75)'
      }
    }, 4000)
    // auto-stop after ~3 minutes (180s)
    setTimeout(function(){ stopBreath(); guide.textContent='Session complete — take a gentle moment.' }, 180000)
  }
  function stopBreath(){ if(breathTimer){ clearInterval(breathTimer); breathTimer=null } }

  function startJournalTimer(){
    var start = Date.now();
    modalStart.disabled = true
    modalSkip.disabled = true
    var seconds = 120
    var info = document.createElement('div')
    info.id='journal-timer'
    info.textContent = 'Write freely for 2 minutes — timer running: 120s'
    modalBody.appendChild(info)
    var t = setInterval(function(){
      var left = seconds - Math.round((Date.now()-start)/1000)
      if(left <= 0){
        clearInterval(t)
        modalStart.disabled = false
        modalSkip.disabled = false
        info.textContent = 'Time is up — consider what surfaced.'
      } else {
        info.textContent = 'Write for: ' + left + 's'
      }
    }, 300)
  }

  // Initialize modal content
  renderModal(currentMode)

  // Small ARIA-friendly escape to close modal
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeModal() })

})();
"} 
